import{_ as t,o,c as u,ag as q}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第120章 存档","description":"","frontmatter":{},"headers":[],"relativePath":"第120章_存档.md","filePath":"第120章_存档.md"}'),e={name:"第120章_存档.md"};function a(_,p,r,n,s,c){return o(),u("div",null,[...p[0]||(p[0]=[q('<h1 id="第120章-存档" tabindex="-1">第120章 存档 <a class="header-anchor" href="#第120章-存档" aria-label="Permalink to &quot;第120章 存档&quot;">​</a></h1><p>那年冬天，我在电脑前面坐了一夜。</p><p>我要做的那件事，我拖了四个月。</p><p>两个子文件夹。</p><p>一个叫&quot;存档&quot;，41 个 G。</p><p>一个没名字，3.4 个 G。</p><p>今年二月我把那三十一条备忘录倒进了第二个里。</p><p>今年十月我把那张&quot;你要记的&quot;表也放进去了。</p><p>今年十二月，第二个文件夹变成 6.1 个 G。</p><p>第一个是她说过的话。</p><p>第二个是她讲不出、我讲不出的话。</p><p>那天夜里我要决定的是：这两个里面，我删一个。</p><p>我先把&quot;存档&quot;打开。</p><p>我从头翻。</p><p>我翻到高一那年冬天，她讲的十一条。</p><p>我那年拄下来，我以为我拄得一字不差。</p><p>我今年对着原始记录核了一遍。</p><p>十一条里我改了两条。</p><p>有一条我把&quot;算了&quot;改成了&quot;算了吧&quot;。</p><p>有三个字我加了两个字。</p><p>我那年不是记不住。</p><p>我那年是在替她把语气改软一点。</p><p>我翻到她说&quot;我他妈在跟你说话&quot;那一年。</p><p>这一句我一个字没改。</p><p>我翻到她说&quot;隔的是一个屋子里能拿起我手机的人&quot;。</p><p>这一句我也没改。</p><p>我那天夜里发现一件事。</p><p>我这十一年改得最多的，是她最疼的那一部分。</p><p>疼的地方我拿手摸过去，我都要把它磨圆一点再放回去。</p><p>我磨圆了它，我就能多看几遍。</p><p>我把这些关上。</p><p>我打开第二个。</p><p>第二个里面是我删掉的。</p><p>我那天早上八点四十四删掉的那一段在里面。</p><p>里面还有那年二月我打了没发出去的一句&quot;你别走&quot;。</p><p>还有我给她写了没寄的一封信。</p><p>还有我数出来的那二百九十三道&quot;以后&quot;。</p><p>还有那句&quot;我今天想说的是我这几年没有一天不在等你&quot;。</p><p>这一句我写过三次。</p><p>一次是那年五月。</p><p>一次是那年十二月。</p><p>一次是二月五号的九点四十三。</p><p>我在输入框里打了，看了，删了。</p><p>三次都在这个文件夹里活着。</p><p>那天夜里三点，我把两个文件夹并排放在一起。</p><p>我知道我该删哪一个。</p><p>我这十一年一直留东西。</p><p>我以为这是我对她做过的一件好事。</p><p>那天夜里我看清楚了它是什么。</p><p>我留，是因为我不敢让她知道我在留。</p><p>我留，是因为留不用开口。</p><p>我留，是因为只要我还留着，我就可以一辈子不跟她讲一句我今天到底要什么。</p><p>我把这十一年存在三个地方：硬盘、网盘、一张八块钱的光盘。</p><p>我一次也没存在一个活人面前。</p><p>而她不一样。</p><p>她这一辈子做的一直是删。</p><p>她删相册，删输入法，删草稿，删号，删那条她打了没发的&quot;我也想你&quot;。</p><p>她删，是因为她不敢让她留着的东西被人看见。</p><p>她删的东西，全部是她在意的东西。</p><p>我们两个拿着同一批话，做了两件相反的事。</p><p>她把在意的删掉。</p><p>我把在意的存起来。</p><p>我们两个谁也没把一句在意的话，当面对那个人讲出来。</p><p>那天夜里四点半，我做了一件事。</p><p>我把&quot;存档&quot;那个文件夹，那 41 个 G，全部留着。</p><p>我把第二个，那 6.1 个 G，删了。</p><p>我删的过程很慢。</p><p>我点了删除，我停了三秒，我点确认。</p><p>那 6.1 个 G 里面，有她讲不出的，和我没讲的。</p><p>我删它是因为那里面没有一句是她说的。</p><p>那里面全部是我替我们两个写的。</p><p>我把它删了，我以后就没有地方可以说&quot;我记得我当时本来要讲&quot;。</p><p>我删完，我在那个位置上重新建了一个文件夹。</p><p>我只起了一个字。</p><p>我起的字是：留。</p><p>我那个新文件夹里现在只放了三样东西。</p><p>那三样我全部当面给过她，或者她当面给过我。</p><p>一张手绘的卡，两个房子，中间一条缝（她寄的，高一）。</p><p>一个瓶盖（她给我的那瓶水，我在食堂拿回来的）。</p><p>一张纸，纸上写着一行&quot;你要记的&quot;，她在第三列的格子上方标了&quot;我做过了&quot;。</p><p>第三列那一格我那天填了。</p><p>我填的是&quot;记了&quot;。</p><p>我填完那张纸我拿手机拍了一张。</p><p>我发给谁，我想了一会儿。</p><p>我发给她了。</p><p>那是我们两年里我发出去的第一句跟货没有关系的话。</p><p>我发过去的时候是这边凌晨四点五十一。</p><p>她那边是夜里十一点五十一。</p><p>她睡了。</p><p>我没有加一句别的话。</p><p>我只发了那一张。</p><p>早上七点我醒来。</p><p>屏幕上有一条。</p><p>她那边上午十点。</p><p>她说，收到了。</p><p>我说，嗯。</p><p>她隔了一分钟。</p><p>她说，你今天不删了吧。</p><p>我说，我不删。</p><p>她说，那我也不删。</p><p>她说，我这边那个抽屉里还有一张你的纸。</p><p>她说，就是那年你挂在门上那一张，画了一个窗。</p><p>她说，我妈那年把它压在鞋柜上，我走的时候我拿上了。</p><p>她说，我今天把它放在我桌上。</p><p>她说，我不放抽屉了。</p><p>我说，好。</p><p>她说，我们两个今年就这样。</p><p>我说，就这样。</p><p>她说，你不要以为这是在跟我和好。</p><p>我说，我知道。</p><p>她说，我们以后还是这样讲话，货的事讲，别的事不讲。</p><p>我说，好。</p><p>她说，你今天做了一件我这三年没想到的事。</p><p>我说，什么。</p><p>她说，你今天把没说的那部分删了，你把说过的留下了。</p><p>她说，你这个人以前不是这样的。</p><p>她说，你以前两个都要留。</p><p>我说，我今年算出来了。</p><p>她说，算出什么。</p><p>我说，两个都留，等于一个都没给出去。</p><p>那天早上我出门上班。</p><p>我在楼下那个早餐摊买了一个包子。</p><p>那个卖包子的人找给我三个一块的硬币。</p><p>我把它们放在掌心里数了一遍。</p><p>数完我塞进裤兜。</p><p>我走到那个路口，绿灯亮了三次我才过去。</p><p>那天我迟到了十九分钟。</p><p>我把电脑打开，我上了她的号那个后台。</p><p>那天有二十三个件要发。</p><p>我一件一件填单。</p><p>我填到第十一单，那个客人名字后面跟了一个括号，括号里是一个代号。</p><p>我那天把二十三个件全部发完。</p><p>我在本子上写了一行。</p><p>我写：这不是结局，是我唯一学会的告别方式。</p><p>我写完，我把本子合上。</p><p>我把那个叫&quot;留&quot;的文件夹关上。</p><p>我把电脑锁了。</p><p>那天下午三点，我出门去驿站。</p><p>驿站里那个小伙子不在，那个女的在。</p><p>她抬头看我。</p><p>她说，今天又是十九件？</p><p>我说，二十三件。</p><p>她说，你最近多了。</p><p>我说，是。</p><p>她把那个扫描枪递给我。</p><p>我接过来，我扫第一件。</p><p>那个枪响了一下。</p>',147)])])}const l=t(e,[["render",a]]);export{d as __pageData,l as default};
